// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }
    function testFuzz_property(uint256 amount1, uint256 amount2) public {
        vm.assume(amount1 <= 1 ether);
        vm.assume(amount2 <= 1 ether);
        address actor = address(0x1234);
        vm.deal(actor, amount1 + amount2);

        vm.prank(actor);
        c.addToBalance{value: amount1}();

        vm.prank(actor);
        bool ok;
        try c.addToBalance{value: amount2}() { ok = true; } catch { ok = false; }

        assertTrue(ok);
    }
}
